mapper.sql:
WHERE o.agreement_status != 'DRAFT'
  AND o.submitted_at IS NOT NULL

    AND o.agreement_status = #{status}


    AND (o.organization_name LIKE '%' || #{keyword} || '%'
         OR o.contact_name LIKE '%' || #{keyword} || '%')


    AND o.submitted_at >= #{from}


    AND o.submitted_at < #{to}
